-- 0073_assist_items_view_columns: the list's view gains plan_at and requested_at (appended: a view's
-- columns may only be added at the end), so the list can say "Drafting" between a request and its
-- answer (ASSIST specs 2.6 step 8). 0065 is unchanged (applied). Grants stay. Undo: re-apply 0065's view.
DO $view$ BEGIN IF to_regclass('biz.emails') IS NOT NULL AND to_regclass('biz.teams_messages') IS NOT NULL THEN EXECUTE $q$CREATE OR REPLACE VIEW assist.matter_items AS SELECT m.matter_id, m.owner_person, m.kind, m.subject_key, m.sources, m.basis_at, m.title, m.detail, m.next_act, m.due_at, m.state, m.verified_at, m.verify_note, m.plan, m.plan_status, m.plan_reason, m.audiences, m.markings, m.counterpart, m.legacy_item_id, m.opened_at, coalesce((SELECT array_agg(DISTINCT h) FROM jsonb_array_elements(CASE WHEN jsonb_typeof(m.sources->'readings') = 'array' THEN m.sources->'readings' ELSE '[]'::jsonb END) s JOIN assist.readings r ON r.source = s->>0 AND r.message_key = s->>1, unnest(r.handles) h), '{}') AS handles, b.source, b.quote, e.sender, e.subject, t.sender AS tsender, m.plan_at, (SELECT max(l.at) FROM assist.matter_log l WHERE l.matter_id = m.matter_id AND l.what = 'requested') AS requested_at FROM assist.matters m LEFT JOIN assist.readings b ON jsonb_typeof(m.sources->'readings') = 'array' AND b.source = m.sources->'readings'->-1->>0 AND b.message_key = m.sources->'readings'->-1->>1 LEFT JOIN LATERAL (SELECT x.sender, x.subject FROM biz.emails x WHERE b.source = 'emails' AND x.handle = b.handles[1] LIMIT 1) e ON true LEFT JOIN LATERAL (SELECT y.sender FROM biz.teams_messages y WHERE b.source = 'teams_messages' AND y.handle = b.handles[1] LIMIT 1) t ON true WHERE m.state IN ('open', 'unverified')$q$; ELSE EXECUTE $q$CREATE OR REPLACE VIEW assist.matter_items AS SELECT m.matter_id, m.owner_person, m.kind, m.subject_key, m.sources, m.basis_at, m.title, m.detail, m.next_act, m.due_at, m.state, m.verified_at, m.verify_note, m.plan, m.plan_status, m.plan_reason, m.audiences, m.markings, m.counterpart, m.legacy_item_id, m.opened_at, coalesce((SELECT array_agg(DISTINCT h) FROM jsonb_array_elements(CASE WHEN jsonb_typeof(m.sources->'readings') = 'array' THEN m.sources->'readings' ELSE '[]'::jsonb END) s JOIN assist.readings r ON r.source = s->>0 AND r.message_key = s->>1, unnest(r.handles) h), '{}') AS handles, b.source, b.quote, NULL::text AS sender, NULL::text AS subject, NULL::text AS tsender, m.plan_at, (SELECT max(l.at) FROM assist.matter_log l WHERE l.matter_id = m.matter_id AND l.what = 'requested') AS requested_at FROM assist.matters m LEFT JOIN assist.readings b ON jsonb_typeof(m.sources->'readings') = 'array' AND b.source = m.sources->'readings'->-1->>0 AND b.message_key = m.sources->'readings'->-1->>1 WHERE m.state IN ('open', 'unverified')$q$; END IF; END $view$;
